-- public.level_skill(p_species text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.level_skill(p_species text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  return (
select coalesce((select g.skill from gather_def g where g.id = sd.gathers), sd.learns,
                  case when sd.draught or sd.mount is not null then haul_skill() end)
    from species_def sd where sd.id = p_species
  );
end $function$
